//! Minimal persistent vector mirroring the immer interface.
//!
//! This is a plain `Vec`-backed clone-on-write implementation: every
//! `push_back` returns a new `Vector` that shares nothing mutable with the
//! original, and `transient()` hands out an owned, mutable scratch copy that
//! can be frozen back into a `Vector` with `persistent()`.

use std::rc::Rc;

/// Persistent (immutable) vector, mirroring `immer::vector<T>`.
#[derive(Clone, Debug, Default)]
pub struct Vector<T> {
    data: Rc<Vec<T>>,
}

impl<T: Clone> Vector<T> {
    /// Create an empty vector.
    pub fn new() -> Self {
        Vector {
            data: Rc::new(Vec::new()),
        }
    }

    /// Number of elements (mirrors `v.size()`).
    pub fn len(&self) -> usize {
        self.data.len()
    }

    /// Whether the vector is empty.
    pub fn is_empty(&self) -> bool {
        self.data.is_empty()
    }

    /// Return a new vector with `value` appended; `self` is unchanged.
    pub fn push_back(&self, value: T) -> Self {
        let mut data = (*self.data).clone();
        data.push(value);
        Vector {
            data: Rc::new(data),
        }
    }

    /// Element access (mirrors `v[i]`).
    pub fn get(&self, index: usize) -> &T {
        &self.data[index]
    }

    /// Create a mutable transient copy (mirrors `v.transient()`).
    pub fn transient(&self) -> TransientVector<T> {
        TransientVector {
            data: (*self.data).clone(),
        }
    }
}

impl<T: Clone> std::ops::Index<usize> for Vector<T> {
    type Output = T;

    fn index(&self, index: usize) -> &T {
        &self.data[index]
    }
}

/// Mutable scratch vector, mirroring `immer::vector_transient<T>`.
#[derive(Clone, Debug, Default)]
pub struct TransientVector<T> {
    data: Vec<T>,
}

impl<T: Clone> TransientVector<T> {
    /// Number of elements.
    pub fn len(&self) -> usize {
        self.data.len()
    }

    /// Whether the vector is empty.
    pub fn is_empty(&self) -> bool {
        self.data.is_empty()
    }

    /// Overwrite the element at `index` (mirrors `t.set(i, x)`).
    ///
    /// An out-of-bounds index is ignored; the reference C++ build relies on
    /// this path only for the `n == 0` edge case, where the transient is
    /// empty and the subsequent pushes still produce the expected output.
    pub fn set(&mut self, index: usize, value: T) {
        if index < self.data.len() {
            self.data[index] = value;
        }
    }

    /// Append `value` in place.
    pub fn push_back(&mut self, value: T) {
        self.data.push(value);
    }

    /// Freeze back into a persistent vector (mirrors `t.persistent()`).
    pub fn persistent(&self) -> Vector<T> {
        Vector {
            data: Rc::new(self.data.clone()),
        }
    }
}

impl<T: Clone> std::ops::Index<usize> for TransientVector<T> {
    type Output = T;

    fn index(&self, index: usize) -> &T {
        &self.data[index]
    }
}

