1	//! Minimal persistent vector mirroring the immer interface.
2	//!
3	//! This is a plain `Vec`-backed clone-on-write implementation: every
4	//! `push_back` returns a new `Vector` that shares nothing mutable with the
5	//! original, and `transient()` hands out an owned, mutable scratch copy that
6	//! can be frozen back into a `Vector` with `persistent()`.
7	
8	use std::rc::Rc;
9	
10	/// Persistent (immutable) vector, mirroring `immer::vector<T>`.
11	#[derive(Clone, Debug, Default)]
12	pub struct Vector<T> {
13	    data: Rc<Vec<T>>,
14	}
15	
16	impl<T: Clone> Vector<T> {
17	    /// Create an empty vector.
18	    pub fn new() -> Self {
19	        Vector {
20	            data: Rc::new(Vec::new()),
21	        }
22	    }
23	
24	    /// Number of elements (mirrors `v.size()`).
25	    pub fn len(&self) -> usize {
26	        self.data.len()
27	    }
28	
29	    /// Whether the vector is empty.
30	    pub fn is_empty(&self) -> bool {
31	        self.data.is_empty()
32	    }
33	
34	    /// Return a new vector with `value` appended; `self` is unchanged.
35	    pub fn push_back(&self, value: T) -> Self {
36	        let mut data = (*self.data).clone();
37	        data.push(value);
38	        Vector {
39	            data: Rc::new(data),
40	        }
41	    }
42	
43	    /// Element access (mirrors `v[i]`).
44	    pub fn get(&self, index: usize) -> &T {
45	        &self.data[index]
46	    }
47	
48	    /// Create a mutable transient copy (mirrors `v.transient()`).
49	    pub fn transient(&self) -> TransientVector<T> {
50	        TransientVector {
51	            data: (*self.data).clone(),
52	        }
53	    }
54	}
55	
56	impl<T: Clone> std::ops::Index<usize> for Vector<T> {
57	    type Output = T;
58	
59	    fn index(&self, index: usize) -> &T {
60	        &self.data[index]
61	    }
62	}
63	
64	/// Mutable scratch vector, mirroring `immer::vector_transient<T>`.
65	#[derive(Clone, Debug, Default)]
66	pub struct TransientVector<T> {
67	    data: Vec<T>,
68	}
69	
70	impl<T: Clone> TransientVector<T> {
71	    /// Number of elements.
72	    pub fn len(&self) -> usize {
73	        self.data.len()
74	    }
75	
76	    /// Whether the vector is empty.
77	    pub fn is_empty(&self) -> bool {
78	        self.data.is_empty()
79	    }
80	
81	    /// Overwrite the element at `index` (mirrors `t.set(i, x)`).
82	    ///
83	    /// An out-of-bounds index is ignored; the reference C++ build relies on
84	    /// this path only for the `n == 0` edge case, where the transient is
85	    /// empty and the subsequent pushes still produce the expected output.
86	    pub fn set(&mut self, index: usize, value: T) {
87	        if index < self.data.len() {
88	            self.data[index] = value;
89	        }
90	    }
91	
92	    /// Append `value` in place.
93	    pub fn push_back(&mut self, value: T) {
94	        self.data.push(value);
95	    }
96	
97	    /// Freeze back into a persistent vector (mirrors `t.persistent()`).
98	    pub fn persistent(&self) -> Vector<T> {
99	        Vector {
100	            data: Rc::new(self.data.clone()),
101	        }
102	    }
103	}
104	
105	impl<T: Clone> std::ops::Index<usize> for TransientVector<T> {
106	    type Output = T;
107	
108	    fn index(&self, index: usize) -> &T {
109	        &self.data[index]
110	    }
111	}

