/// Replicate the uncaught-exception path of the C++ binary: libstdc++ prints
/// the terminate message and aborts (SIGABRT, exit code 134).
fn stoi_throw(exception: &str) -> ! {
    eprintln!("terminate called after throwing an instance of 'std::{}'", exception);
    eprintln!("  what():  stoi");
    std::process::abort();
}

/// Parse like C++ `std::stoi`: skip leading whitespace, accept an optional
/// `+`/`-` sign, then parse leading digits. Like the reference binary, aborts
/// with `std::invalid_argument` when there are no digits and with
/// `std::out_of_range` when the value does not fit in a C++ `int`.
fn stoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut idx = 0;
    while idx < bytes.len()
        && matches!(bytes[idx], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
    {
        idx += 1;
    }
    let mut negative = false;
    if idx < bytes.len() && (bytes[idx] == b'+' || bytes[idx] == b'-') {
        negative = bytes[idx] == b'-';
        idx += 1;
    }
    let digit_start = idx;
    let mut value: i64 = 0;
    while idx < bytes.len() && bytes[idx].is_ascii_digit() {
        // Cap accumulation: anything past 2^31 is already out of range.
        if value <= 2_147_483_648 {
            value = value * 10 + i64::from(bytes[idx] - b'0');
        }
        idx += 1;
    }
    if idx == digit_start {
        stoi_throw("invalid_argument");
    }
    if value > 2_147_483_648 || (!negative && value == 2_147_483_648) {
        stoi_throw("out_of_range");
    }
    if negative {
        value = -value;
    }
    value as i32
}

