/// Return a new vector with `value` appended (mirrors `v.push_back(x)`).
///
/// Takes `self` by value so the natural `v = v.push_back(x)` idiom reuses
/// the allocation in place when the vector is not shared (`Rc::make_mut`
/// on a unique `Rc` mutates without cloning), giving amortized O(1)
/// pushes; a shared vector is cloned first, preserving persistence.
pub fn push_back(self, value: T) -> Self {
    let mut data = self.data;
    Rc::make_mut(&mut data).push(value);
    Vector { data }
}

